                document.getElementById('mizuki-outfit-underwear').innerText = SafeGetValue(characterData, '装扮.内衣', 'N/A');
                document.getElementById('mizuki-outfit-foot').innerText = SafeGetValue(characterData, '装扮.足部', 'N/A');
            }

            if (characterData.hasOwnProperty('身体')) {
                document.getElementById('mizuki-body-mouth').innerText = SafeGetValue(characterData, '身体.口腔', 'N/A');
                document.getElementById('mizuki-body-breasts').innerText = SafeGetValue(characterData, '身体.胸部', 'N/A');
                document.getElementById('mizuki-body-vagina').innerText = SafeGetValue(characterData, '身体.小穴', 'N/A');
                document.getElementById('mizuki-body-anus').innerText = SafeGetValue(characterData, '身体.菊穴', 'N/A');
            }

        } catch (error) {
            console.error("状态栏加载出错: ", error);
        }
    }

